<script setup lang="ts">import{computed}from 'vue';const p=defineProps<{trace:{iteration:number;max_residual:number}[]}>();const points=computed(()=>p.trace.map((t,i)=>`${35+i*720/Math.max(1,p.trace.length-1)},${35+(Math.min(-1,Math.max(-8,Math.log10(Math.max(1e-8,t.max_residual))))+1)/-7*175}`).join(' '));</script><template><div class="chart"><div class="section-heading"><h3>收敛轨迹</h3><span>归一残差 / 对数刻度</span></div><svg viewBox="0 0 800 260" aria-label="权重迭代残差收敛曲线" role="img"><g class="grid"><line v-for="y in [35,95,155,215]" :key="y" x1="35" x2="755" :y1="y" :y2="y"/></g><polyline :points="points" fill="none" stroke="currentColor" stroke-width="3"/><text x="35" y="250">第1次迭代</text><text x="640" y="250">第{{trace.length}}次迭代</text><text x="5" y="38">10⁻¹</text><text x="5" y="217">10⁻⁸</text></svg></div></template>
